/**
 * Theme toggle — exact Figma "Light Dark Toggle" (node 1:23107):
 * peachy orange gradient track, white inactive icon on the track, and a solid
 * #D45427 circular knob (with white active icon) on the active side.
 * Light: sun knob (right) + moon inactive (left). Dark: moon knob (left) + sun inactive (right).
 * `inline` sits it in the dashboard header; default is a fixed floating control.
 */
export default function ThemeToggle({ inline = false }) {
  const { theme, toggleTheme } = useTheme();
  const isDark = theme === "dark";

  const W = 76;
  const H = 40;
  const KNOB = 32;
  const PAD = 4;
  const translateX = W - (KNOB + PAD * 2);

  const gradient =
    "linear-gradient(118deg, rgba(212,84,39,0.5) 11%, rgba(245,158,11,0.5) 88%)";

  return (
    <button
      type="button"
      aria-label="Toggle dark/light mode"
      aria-pressed={isDark}
      onClick={toggleTheme}
      title={isDark ? "Switch to light mode" : "Switch to dark mode"}
      className={
        inline
          ? "relative shrink-0"
          : "fixed z-50 right-2 sm:right-4 md:right-6 top-3 sm:top-10 md:top-12 lg:top-5"
      }
      style={{ width: W, height: H }}
    >
      <div
        className="relative w-full h-full rounded-full overflow-hidden"
        style={{ backgroundImage: gradient }}
      >
        {/* Inactive icon on the track (white): dark -> sun (right), light -> moon (left) */}
        {isDark ? (
          <span className="absolute right-[10px] top-1/2 -translate-y-1/2">
            <SunIcon size={20} color="#F9FAFB" />
          </span>
        ) : (
          <span className="absolute left-[10px] top-1/2 -translate-y-1/2">
            <MoonIcon size={20} color="#F9FAFB" />
          </span>
        )}

        {/* Solid #D45427 knob with the ACTIVE icon (white) */}
        <div
          className="absolute rounded-full flex items-center justify-center shadow-[0_2px_5px_rgba(0,0,0,0.25)] transition-transform duration-300 ease-out"
          style={{
            width: KNOB,
            height: KNOB,
            top: PAD,
            left: PAD,
            background: "#D45427",
            transform: `translateX(${isDark ? 0 : translateX}px)`,
          }}
        >
          {isDark ? (
            <MoonIcon size={20} color="#191A1A" />
          ) : (
            <SunIcon size={20} color="#FFFFFF" />
          )}
        </div>
      </div>
    </button>
  );
}
